#include <iostream>

int main() {
    const int CITIES = 3; // Chicago, Boston, New York
    int distances[CITIES][CITIES] = {
        {0, 983, 787},
        {983, 0, 214},
        {787, 214, 0}
    };

    // Access distance from Boston (row 1) to New York (column 2)
    std::cout << "Distance from Boston to NY: " << distances[1][2] << " miles\n";

    // Assign an updated road detour distance
    distances[1][2] = 220;
    std::cout << "Updated distance: " << distances[1][2] << " miles\n";

    return 0;
}

#include <iostream>

int main() {
    const int ROWS = 3;
    const int COLS = 4;
    int matrix[ROWS][COLS] = {
        {2, 4, 3, 5},
        {9, 1, 6, 2},
        {7, 8, 4, 3}
    };

    // 1. Display matrix
    std::cout << "Matrix:\n";
    for (int r = 0; r < ROWS; ++r) {
        for (int c = 0; c < COLS; ++c) {
            std::cout << matrix[r][c] << " ";
        }
        std::cout << "\n";
    }

    // 2. Sum all elements
    int total = 0;
    for (int r = 0; r < ROWS; ++r) {
        for (int c = 0; c < COLS; ++c) {
            total += matrix[r][c];
        }
    }
    std::cout << "Total sum: " << total << "\n";

    // 3. Sum by column
    for (int c = 0; c < COLS; ++c) {
        int colSum = 0;
        for (int r = 0; r < ROWS; ++r) {
            colSum += matrix[r][c];
        }
        std::cout << "Sum for column " << c << " is " << colSum << "\n";
    }

    // 4. Find row with largest sum
    int maxRow = 0;
    int indexOfMaxRow = 0;
    for (int c = 0; c < COLS; ++c) {
        maxRow += matrix[0][c];
    }

    for (int r = 1; r < ROWS; ++r) {
        int currentSum = 0;
        for (int c = 0; c < COLS; ++c) {
            currentSum += matrix[r][c];
        }
        if (currentSum > maxRow) {
            maxRow = currentSum;
            indexOfMaxRow = r;
        }
    }
    std::cout << "Row " << indexOfMaxRow << " has the maximum sum of " << maxRow << "\n";

    return 0;
}
